function getPath(obj,path){return path.split('.').reduce((o,k)=>o?.[k],obj)}
function setPath(obj,path,value){const bits=path.split('.');if(bits.some(k=>!k||['__proto__','prototype','constructor'].includes(k)))throw new Error('Invalid setting path');let o=obj;for(let i=0;i<bits.length-1;i++){if(!o[bits[i]]||typeof o[bits[i]]!=='object')o[bits[i]]={};o=o[bits[i]]}o[bits.at(-1)]=value}
function fmt(v){v=+v;if(!Number.isInteger(v))return(v>0?'+':'')+v.toFixed(2);return(v>0?'+':'')+v}
function safeText(s){const d=document.createElement('div');d.textContent=String(s??'');return d.innerHTML}
function safeAttr(s){return safeText(s).replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function toast(s){const t=$('#toast');if(!t)return; t.textContent=s;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3200)}
function dismissToast(){const t=$('#toast');if(!t)return;clearTimeout(t.timer);t.classList.remove('show')}
