function writeTutorialState(value){try{localStorage.setItem(TUTORIAL_KEY,value)}catch(error){console.warn('[Luma] Could not remember tutorial state',error)}}
function hasSeenTutorial(){try{return!!localStorage.getItem(TUTORIAL_KEY)}catch{return false}}
function clearTutorialTarget(){if(tutorialTarget)tutorialTarget.classList.remove('tutorial-target');tutorialTarget=null}
function tutorialElement(step=tutorialSteps[tutorialStep]){
  const selector=typeof step?.target==='function'?step.target():step?.target,element=selector?$(selector):null;
  if(!element)return null;const style=getComputedStyle(element),rect=element.getBoundingClientRect();return style.display==='none'||style.visibility==='hidden'||rect.width<1||rect.height<1?null:element
}
function placeTutorial(){
  const dialog=$('#tutorialDialog');if(!dialog?.open)return;const target=tutorialTarget,viewportWidth=window.innerWidth,viewportHeight=window.innerHeight,pad=12,gap=14,width=dialog.offsetWidth,height=dialog.offsetHeight;
  if(!target){dialog.style.left=`${Math.max(pad,(viewportWidth-width)/2)}px`;dialog.style.top=`${Math.max(pad,(viewportHeight-height)/2)}px`;return}
  const rect=target.getBoundingClientRect(),clamp=(value,min,max)=>Math.max(min,Math.min(max,value)),alignY=clamp(rect.top,pad,Math.max(pad,viewportHeight-height-pad)),alignX=clamp(rect.left,pad,Math.max(pad,viewportWidth-width-pad));
  const candidates=[{left:rect.right+gap,top:alignY},{left:rect.left-width-gap,top:alignY},{left:alignX,top:rect.bottom+gap},{left:alignX,top:rect.top-height-gap}],fits=point=>point.left>=pad&&point.top>=pad&&point.left+width<=viewportWidth-pad&&point.top+height<=viewportHeight-pad,choice=candidates.find(fits)||{left:clamp((viewportWidth-width)/2,pad,Math.max(pad,viewportWidth-width-pad)),top:clamp((viewportHeight-height)/2,pad,Math.max(pad,viewportHeight-height-pad))};
  dialog.style.left=`${Math.round(choice.left)}px`;dialog.style.top=`${Math.round(choice.top)}px`
}
function renderTutorialStep({focus=true}={}){
  const step=tutorialSteps[tutorialStep];if(!step)return;step.prepare?.();clearTutorialTarget();tutorialTarget=tutorialElement(step);tutorialTarget?.classList.add('tutorial-target');
  $('#tutorialStepLabel').textContent=`STEP ${tutorialStep+1} OF ${tutorialSteps.length}`;$('#tutorialTitle').textContent=step.title;$('#tutorialCopy').textContent=step.copy;$('#tutorialHint').textContent=step.hint||'';$('#tutorialBack').disabled=tutorialStep===0;$('#tutorialNext').textContent=tutorialStep===tutorialSteps.length-1?'Finish':'Next';
  const progress=$('#tutorialProgress');progress.replaceChildren(...tutorialSteps.map((_item,index)=>{const marker=document.createElement('i');marker.className=index<tutorialStep?'complete':index===tutorialStep?'current':'';return marker}));
  requestAnimationFrame(()=>{placeTutorial();if(focus)$('#tutorialNext').focus()})
}
function finishTutorial(state='complete'){
  const dialog=$('#tutorialDialog');writeTutorialState(state);clearTutorialTarget();document.body.classList.remove('tutorial-active');if(dialog?.open)dialog.close(state);const returnTo=tutorialReturnFocus;tutorialReturnFocus=null;requestAnimationFrame(()=>{if(returnTo?.isConnected&&!returnTo.closest('dialog:not([open])'))returnTo.focus();else $('#helpBtn')?.focus()})
}
function startTutorial(){
  const dialog=$('#tutorialDialog');if(!dialog)return;$$('dialog[open]').forEach(openDialog=>{if(openDialog!==dialog)openDialog.close()});tutorialReturnFocus=$('#helpBtn');tutorialStep=0;document.body.classList.add('tutorial-active');if(!dialog.open)dialog.showModal();renderTutorialStep()
}
function openHelpCenter(){
  const dialog=$('#helpDialog');if(!dialog)return;if($('#tutorialDialog')?.open)finishTutorial('skipped');$$('dialog[open]').forEach(openDialog=>{if(openDialog!==dialog)openDialog.close()});if(dialog.open){$('#startTutorialBtn').focus();return}helpReturnFocus=document.activeElement;dialog.showModal();requestAnimationFrame(()=>$('#startTutorialBtn').focus())
}
async function openHelpGuide(){
  const status=$('#guideStatus'),button=$('#openGuideBtn');status.classList.remove('hidden');status.textContent='Opening the guide…';button.disabled=true;
  try{
    const result=await window.desktop?.openHelpGuide?.();
    if(result?.opened)status.textContent='The installation and user guide opened in your browser.';
    else if(result?.reason==='not-configured')status.textContent='The online guide is not published in this build yet. The tutorial and shortcuts above remain available offline.';
    else status.textContent='The guide could not be opened securely. Please use the in-app tutorial for now.'
  }catch(error){console.warn('[Luma] Open help guide',error);status.textContent='The guide could not be opened. Please use the in-app tutorial for now.'}
  finally{button.disabled=false}
}
function scheduleFirstRunTutorial(){if(hasSeenTutorial())return;setTimeout(()=>{if(!document.querySelector('dialog[open]'))startTutorial()},450)}
function reportFailure(context,error,message='Something went wrong. Your catalog and edits are still available.'){
  console.error(`[Luma] ${context}`,error);const now=Date.now();if(now-lastErrorToastAt>3500){lastErrorToastAt=now;toast(message)}
}
function runAsync(context,task,message){return Promise.resolve().then(task).catch(error=>reportFailure(context,error,message))}
function checksum(text){let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16)}
function isBackupCandidate(raw){try{const data=JSON.parse(raw),list=Array.isArray(data)?data:data?.photos;return Array.isArray(list)&&list.length<=MAX_CATALOG_PHOTOS&&(!data?.checksum||checksum(JSON.stringify(list))===data.checksum)}catch{return false}}
function catalogRecords(){return photos.map(p=>({id:p.id,filePath:p.filePath,name:p.name,edits:p.edits,rating:p.rating,flag:p.flag,label:p.label,tags:p.tags,caption:p.caption,quality:p.quality,importedAt:p.importedAt}))}
function makeCatalogPayload(){const records=catalogRecords(),body=JSON.stringify(records);if(body.length>MAX_CATALOG_BYTES)throw new RangeError('The catalog is too large for local storage.');const savedAt=Date.now();catalogGeneration=Math.max(catalogGeneration+1,savedAt);return JSON.stringify({app:'Luma Darkroom',version:2,savedAt,generation:catalogGeneration,checksum:checksum(body),photos:records})}
function storageGet(key){try{return localStorage.getItem(key)}catch(error){reportFailure('Read catalog storage',error,'Catalog storage is unavailable. Back up your catalog before closing.');return null}}
function storageRemove(key){try{localStorage.removeItem(key)}catch(error){console.warn(`[Luma] Could not remove ${key}`,error)}}
function watermarkHistory(){try{const list=JSON.parse(storageGet(WATERMARK_KEY)||'[]');return Array.isArray(list)?list.filter(v=>typeof v==='string'&&v.trim()).map(v=>v.trim().slice(0,80)).slice(0,3):[]}catch{return[]}}
function refreshWatermarkHistory(){const list=$('#watermarkHistory');if(!list)return;list.replaceChildren(...watermarkHistory().map(value=>{const option=document.createElement('option');option.value=value;return option}))}
function rememberWatermark(value){value=String(value||'').trim().slice(0,80);if(!value)return;const next=[value,...watermarkHistory().filter(item=>item!==value)].slice(0,3);try{localStorage.setItem(WATERMARK_KEY,JSON.stringify(next));refreshWatermarkHistory()}catch(error){console.warn('[Luma] Could not remember watermark',error)}}
function isQuotaError(error){return error?.name==='QuotaExceededError'||error?.code===22||error?.code===1014}
function saveCatalog({silent=false}={}){
  clearTimeout(saveTimer);saveTimer=null;let payload;
  try{payload=makeCatalogPayload()}catch(error){catalogDirty=true;reportFailure('Serialize catalog',error,'Catalog could not be autosaved. Export a catalog backup before closing.');return false}
  const previous=storageGet(CATALOG_KEY);let recoveryWritten=false;
  try{
    if(previous&&previous.length<=MAX_BACKUP_BYTES&&isBackupCandidate(previous))try{localStorage.setItem(BACKUP_KEY,previous)}catch{}
    try{localStorage.setItem(RECOVERY_KEY,payload);recoveryWritten=true}catch(error){if(!isQuotaError(error))throw error;storageRemove(RECOVERY_KEY)}
    try{localStorage.setItem(CATALOG_KEY,payload)}catch(firstError){
      if(!isQuotaError(firstError))throw firstError;storageRemove(BACKUP_KEY);
      try{localStorage.setItem(CATALOG_KEY,payload)}catch(secondError){if(recoveryWritten){storageRemove(RECOVERY_KEY);recoveryWritten=false;localStorage.setItem(CATALOG_KEY,payload)}else throw secondError}
    }
    storageRemove(RECOVERY_KEY);catalogDirty=false;return true;
  }catch(error){
    catalogDirty=true;const now=Date.now();if(!silent&&now-lastSaveErrorAt>10_000){lastSaveErrorAt=now;reportFailure('Save catalog',error,isQuotaError(error)?'Catalog storage is full. Save a catalog backup before closing.':'Catalog autosave failed. Save a catalog backup before closing.')}return false;
  }
}
function debounceSave(){catalogDirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCatalog(),300)}
function flushCatalog(){if(catalogDirty)saveCatalog({silent:true})}
function touchHistory(id){if(!id)return;historyLru.delete(id);historyLru.set(id,Date.now());while(historyLru.size>MAX_HISTORY_PHOTOS){const oldest=historyLru.keys().next().value;historyLru.delete(oldest);undoByPhoto.delete(oldest);redoByPhoto.delete(oldest)}}
function historyStacks(){const id=current?.id;if(!id)return[[],[]];touchHistory(id);if(!undoByPhoto.has(id))undoByPhoto.set(id,[]);if(!redoByPhoto.has(id))redoByPhoto.set(id,[]);return[undoByPhoto.get(id),redoByPhoto.get(id)]}
function pushHistory(before,after,label='Edit'){
  if(!current)return;let beforeJson,afterJson;try{beforeJson=JSON.stringify(before);afterJson=JSON.stringify(after)}catch(error){reportFailure('Capture edit history',error,'This edit was applied, but could not be added to undo history.');return}
  if(beforeJson===afterJson)return;if(beforeJson.length+afterJson.length>MAX_HISTORY_ENTRY_BYTES){toast('Edit applied · undo history skipped for this large change');return}
  const[u,r]=historyStacks();u.push({before:JSON.parse(beforeJson),after:JSON.parse(afterJson),label:String(label).slice(0,100)});if(u.length>MAX_HISTORY_ENTRIES)u.splice(0,u.length-MAX_HISTORY_ENTRIES);r.length=0;updateUndoButtons()
}
function pushBulkHistory(changes,label='Batch edit'){
  if(!current||!changes.length)return false;let json;try{json=JSON.stringify(changes.map(change=>({id:change.id,before:change.before,after:change.after})))}catch(error){reportFailure('Capture batch history',error,'The batch edit was not applied because its undo record could not be created.');return false}
  if(json.length>MAX_HISTORY_ENTRY_BYTES){toast('Select fewer photographs so this batch can remain undoable');return false}const[u,r]=historyStacks();u.push({bulk:JSON.parse(json),label:String(label).slice(0,100)});if(u.length>MAX_HISTORY_ENTRIES)u.splice(0,u.length-MAX_HISTORY_ENTRIES);r.length=0;updateUndoButtons();return true
}
function applyHistoryItem(item,state){if(item.bulk){for(const change of item.bulk){const photo=photos.find(candidate=>candidate.id===change.id);if(photo)photo.edits=E.clone(change[state])}}else if(current)current.edits=E.clone(item[state])}
function clearPresetTracking(){activePreset=null;presetBase=null}
function updateUndoButtons(){if(!current){$('#undoBtn').disabled=$('#redoBtn').disabled=true;return}const[u,r]=historyStacks();$('#undoBtn').disabled=!u.length;$('#redoBtn').disabled=!r.length}
function commit(label,fn){if(!current)return;clearPresetTracking();let before;try{before=E.clone(current.edits);fn();current.edits=E.migratedEdits(current.edits)}catch(error){if(before)current.edits=before;reportFailure(`Apply ${label}`,error,'That edit could not be applied; the previous settings were restored.');refreshControls();scheduleRender();return}pushHistory(before,current.edits,label);refreshControls();scheduleRender();debounceSave()}

function controlId(path){return`control-${path.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}`}
function range(path,label,min,max,step=1,extra=''){const id=controlId(path);return`<div class="control ${extra}"><label for="${id}">${label}<output data-out="${path}" for="${id}">0</output></label><input id="${id}" aria-label="${label}" data-path="${path}" type="range" min="${min}" max="${max}" step="${step}" value="0"></div>`}
function panel(name,body,open=true){const id=`panel-${name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}`,bodyId=`${id}-body`;return`<section class="panel ${open?'':'collapsed'}" data-panel-name="${name}"><div class="panel-title-row"><button class="panel-head" aria-expanded="${open}" aria-controls="${bodyId}">${name}</button><button class="reset-one" aria-label="Reset ${name}">reset</button></div><div class="panel-body" id="${bodyId}">${body}</div></section>`}

function buildAdjustments(){
  const profile=`<div class="select-control"><label for="profileSelect">Profile</label><select id="profileSelect" data-select-path="profile"><option>Luma Color</option><option>Luma Vivid</option><option>Luma Neutral</option><option>Luma Portrait</option><option>Luma Landscape</option><option>Monochrome</option></select></div>${range('profileAmount','Amount',0,200,1)}<label class="check-row">Black & white<input type="checkbox" data-check-path="bw"></label>`;
  const light=`<div class="auto-row"><button id="autoTone">Auto</button><button id="clipToggle" aria-pressed="false">Clipping</button><button id="toneReset">Reset tone</button></div>${sliderPanels.Light.map(x=>range(...x)).join('')}`;
  const curve=`<div class="curve-toolbar" aria-label="Tone curve channel">${['rgb','red','green','blue'].map(c=>`<button data-curve-channel="${c}" aria-pressed="false">${c.toUpperCase()}</button>`).join('')}</div><div class="curve-wrap"><canvas id="curveCanvas" width="300" height="165" role="img" aria-label="Tone curve editor; use presets below for a keyboard alternative"></canvas></div><div class="button-row"><button data-curve-preset="linear">Linear</button><button data-curve-preset="medium">Medium</button><button data-curve-preset="strong">Strong</button></div>${range('curve.refineSaturation','Refine saturation',-100,100,1)}<div class="curve-help">Click to add · drag to adjust · double-click a point to remove</div>`;
  const color=`<div class="select-control"><label for="whiteBalanceSelect">White balance</label><select id="whiteBalanceSelect" data-select-path="color.wb"><option>As Shot</option><option>Auto</option><option>Daylight</option><option>Cloudy</option><option>Shade</option><option>Tungsten</option><option>Fluorescent</option><option>Flash</option></select></div>${range('color.temperature','Temperature',-100,100,1)}${range('color.tint','Tint',-100,100,1)}${range('color.vibrance','Vibrance',-100,100,1)}${range('color.saturation','Saturation',-100,100,1)}`;
  const mixer=`<div class="mixer-colors" aria-label="Color mixer range">${E.COLORS.map(c=>`<button class="color-chip" data-color="${c}" title="${c}" aria-label="${c} color range" aria-pressed="false"></button>`).join('')}</div><div id="mixerSliders"></div><button id="mixerPicker" class="mini-btn">⌖ Target HSL range</button><div class="subhead">POINT COLOR</div><label class="check-row">Enable point color<input type="checkbox" data-check-path="pointColor.enabled"></label><div class="point-swatch" id="pointSwatch"></div>${range('pointColor.hueShift','Hue shift',-100,100,1)}${range('pointColor.saturationShift','Saturation shift',-100,100,1)}${range('pointColor.luminanceShift','Luminance shift',-100,100,1)}${range('pointColor.variance','Variance',0,100,1)}${range('pointColor.range','Range',1,100,1)}<label class="check-row">Visualize range<input type="checkbox" data-check-path="pointColor.visualize"></label><button id="pointColorPicker" class="mini-btn">⌖ Pick point color</button>`;
  const grading=`<div class="grading-tabs" aria-label="Color grading range">${['shadows','midtones','highlights','global'].map(c=>`<button data-grade="${c}" aria-label="${c} grading" aria-pressed="false">${c[0].toUpperCase()}</button>`).join('')}</div><div id="gradingSliders"></div>${range('grading.blending','Blending',0,100,1)}${range('grading.balance','Balance',-100,100,1)}`;
  const optics=`<label class="check-row">Remove chromatic aberration<input type="checkbox" data-check-path="optics.removeCA"></label><label class="check-row">Enable lens corrections<input type="checkbox" data-check-path="optics.lensCorrections"></label>${range('optics.distortion','Lens distortion',-100,100,1)}${range('optics.lensVignette','Lens vignetting',-100,100,1)}${range('optics.defringePurple','Purple defringe',0,100,1)}${range('optics.defringeGreen','Green defringe',0,100,1)}`;
  const geometry=`<div class="select-control"><label for="cropAspectSelect">Crop aspect</label><select id="cropAspectSelect" data-select-path="geometry.cropAspect"><option>Original</option><option>Square</option><option>4 × 5</option><option>5 × 4</option><option>2 × 3</option><option>3 × 2</option><option>9 × 16</option><option>16 × 9</option></select></div><div class="button-row"><button data-upright="auto">Reset upright</button><button data-upright="level">Reset level</button><button data-upright="full">Reset full</button></div>${sliderPanels.Geometry.map(x=>range(...x)).join('')}<label class="check-row">Constrain crop<input type="checkbox" data-check-path="geometry.constrainCrop"></label>`;
  $('#adjustments').innerHTML=panel('Profile',profile)+panel('Light',light)+panel('Tone Curve',curve)+panel('Color',color)+panel('Color Mixer',mixer)+panel('Color Grading',grading)+panel('Effects',sliderPanels.Effects.map(x=>range(...x)).join(''),false)+panel('Detail',sliderPanels.Detail.map(x=>range(...x)).join(''),false)+panel('Optics',optics,false)+panel('Crop & Geometry',geometry,false);
  buildMixerSliders();buildGradingSliders();bindAdjustmentEvents();drawCurve();
}
function buildMixerSliders(){$('#mixerSliders').innerHTML=['hue','saturation','luminance'].map(k=>range(`mixer.${mixerColor}.${k}`,k[0].toUpperCase()+k.slice(1),-100,100,1)).join('');bindRanges($('#mixerSliders'));$$('.color-chip').forEach(b=>{const active=b.dataset.color===mixerColor;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});refreshControls()}
function buildGradingSliders(){$('#gradingSliders').innerHTML=range(`grading.${gradingTarget}.hue`,'Hue',0,360,1,'gradient-hue')+range(`grading.${gradingTarget}.saturation`,'Saturation',0,100,1)+range(`grading.${gradingTarget}.luminance`,'Luminance',-100,100,1);bindRanges($('#gradingSliders'));$$('[data-grade]').forEach(b=>{const active=b.dataset.grade===gradingTarget;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});refreshControls()}
function bindRanges(root=document){root.querySelectorAll('input[data-path]').forEach(el=>{let before=null,photoId=null;const begin=()=>{if(!current)return false;clearPresetTracking();if(!before||photoId!==current.id){before=E.clone(current.edits);photoId=current.id}return true},finish=()=>{if(before&&current?.id===photoId)pushHistory(before,current.edits,el.dataset.path);before=null;photoId=null};el.onpointerdown=begin;el.oninput=()=>{if(!begin())return;setPath(current.edits,el.dataset.path,+el.value);const out=document.querySelector(`[data-out="${el.dataset.path}"]`);if(out)out.value=fmt(el.value);scheduleRender();debounceSave()};el.onchange=finish;el.onblur=finish;el.onpointercancel=finish})}
function bindAdjustmentEvents(){
  bindRanges($('#adjustments'));
  $$('.panel-head').forEach(b=>b.onclick=()=>{const panel=b.closest('.panel'),collapsed=panel.classList.toggle('collapsed');b.setAttribute('aria-expanded',String(!collapsed));if(panel.dataset.panelName==='Tone Curve')drawCurve()});
  $$('.reset-one').forEach(b=>b.onclick=e=>{e.stopPropagation();resetPanel(b.closest('.panel').dataset.panelName)});
  $$('[data-select-path]').forEach(el=>el.onchange=()=>commit(el.dataset.selectPath,()=>{setPath(current.edits,el.dataset.selectPath,el.value);if(el.dataset.selectPath==='color.wb')applyWB(el.value)}));
  $$('[data-check-path]').forEach(el=>el.onchange=()=>commit(el.dataset.checkPath,()=>setPath(current.edits,el.dataset.checkPath,el.checked)));
  $$('.color-chip').forEach(b=>b.onclick=()=>{mixerColor=b.dataset.color;buildMixerSliders()});
  $$('[data-grade]').forEach(b=>b.onclick=()=>{gradingTarget=b.dataset.grade;buildGradingSliders()});
  $$('[data-curve-channel]').forEach(b=>b.onclick=()=>{curveChannel=b.dataset.curveChannel;drawCurve()});
  $$('[data-curve-preset]').forEach(b=>b.onclick=()=>commit('Curve preset',()=>{const pts={linear:[[0,0],[255,255]],medium:[[0,0],[64,52],[128,128],[192,204],[255,255]],strong:[[0,0],[55,35],[128,128],[205,230],[255,255]]}[b.dataset.curvePreset];current.edits.curve[curveChannel]=pts}));
  $('#autoTone').onclick=autoTone;$('#toneReset').onclick=()=>resetPanel('Light');$('#clipToggle').onclick=()=>{clipping=!clipping;$('#clipToggle').classList.toggle('active',clipping);$('#clipToggle').setAttribute('aria-pressed',String(clipping));scheduleRender()};$('#mixerPicker').onclick=()=>setTool('color');$('#pointColorPicker').onclick=()=>setTool('point');
  $$('[data-upright]').forEach(b=>b.onclick=()=>commit('Upright',()=>{const mode=b.dataset.upright;if(mode==='level')current.edits.geometry.straighten=0;if(mode==='auto'){current.edits.geometry.vertical=0;current.edits.geometry.horizontal=0;current.edits.geometry.straighten=0}if(mode==='full'){current.edits.geometry.vertical=0;current.edits.geometry.horizontal=0;current.edits.geometry.aspect=0}}));
  bindCurveEvents();
}
function applyWB(mode){const vals={"As Shot":[0,0],Auto:[0,0],Daylight:[8,0],Cloudy:[15,1],Shade:[24,2],Tungsten:[-35,0],Fluorescent:[-18,12],Flash:[10,2]}[mode]||[0,0];current.edits.color.temperature=vals[0];current.edits.color.tint=vals[1]}
function resetPanel(name){const d=E.defaultEdits(),map={Profile:['profile','profileAmount','bw'],Light:['light'],'Tone Curve':['curve'],Color:['color'],'Color Mixer':['mixer','pointColor'],'Color Grading':['grading'],Effects:['effects'],Detail:['detail'],Optics:['optics'],'Crop & Geometry':['geometry']};commit(`Reset ${name}`,()=>map[name].forEach(k=>current.edits[k]=E.clone(d[k])))}
function refreshControls(){if(!current)return;$$('input[data-path]').forEach(el=>{const v=getPath(current.edits,el.dataset.path);if(v!=null){el.value=v;const out=document.querySelector(`[data-out="${el.dataset.path}"]`);if(out)out.value=fmt(v)}});$$('[data-select-path]').forEach(el=>{const v=getPath(current.edits,el.dataset.selectPath);if(v!=null)el.value=v});$$('[data-check-path]').forEach(el=>el.checked=!!getPath(current.edits,el.dataset.checkPath));if($('#pointSwatch'))$('#pointSwatch').style.background=`hsl(${current.edits.pointColor.hue} 75% 50%)`;drawCurve();updateMaskUI();updateUndoButtons()}

function drawCurve(){const c=$('#curveCanvas');if(!c||!current)return;const x=c.getContext('2d'),w=c.width,h=c.height,pts=current.edits.curve[curveChannel];x.clearRect(0,0,w,h);x.fillStyle='#111416';x.fillRect(0,0,w,h);x.strokeStyle='#2d3439';x.lineWidth=1;for(let i=1;i<4;i++){x.beginPath();x.moveTo(w*i/4,0);x.lineTo(w*i/4,h);x.stroke();x.beginPath();x.moveTo(0,h*i/4);x.lineTo(w,h*i/4);x.stroke()}x.strokeStyle='#4c555d';x.beginPath();x.moveTo(0,h);x.lineTo(w,0);x.stroke();x.strokeStyle={rgb:'#edf3f7',red:'#ff6b6b',green:'#68d486',blue:'#6da3ff'}[curveChannel];x.lineWidth=2;x.beginPath();pts.slice().sort((a,b)=>a[0]-b[0]).forEach((p,i)=>{const px=p[0]/255*w,py=h-p[1]/255*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke();x.fillStyle=x.strokeStyle;pts.forEach(p=>{x.beginPath();x.arc(p[0]/255*w,h-p[1]/255*h,4,0,Math.PI*2);x.fill()});$$('[data-curve-channel]').forEach(b=>{const active=b.dataset.curveChannel===curveChannel;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function bindCurveEvents(){const c=$('#curveCanvas');let point=null,before=null;const pos=e=>{const r=c.getBoundingClientRect();return[Math.round((e.clientX-r.left)/r.width*255),Math.round(255-(e.clientY-r.top)/r.height*255)]};c.onpointerdown=e=>{if(!current)return;clearPresetTracking();before=E.clone(current.edits);const [px,py]=pos(e),pts=current.edits.curve[curveChannel];point=pts.find(p=>Math.hypot(p[0]-px,p[1]-py)<18);if(!point){point=[px,py];pts.push(point);pts.sort((a,b)=>a[0]-b[0])}c.setPointerCapture(e.pointerId);drawCurve()};c.onpointermove=e=>{if(!point)return;const[px,py]=pos(e),pts=current.edits.curve[curveChannel],isEnd=point[0]===0||point[0]===255;point[0]=isEnd?point[0]:Math.max(1,Math.min(254,px));point[1]=Math.max(0,Math.min(255,py));pts.sort((a,b)=>a[0]-b[0]);drawCurve();scheduleRender()};c.onpointerup=()=>{if(before)pushHistory(before,current.edits,'Tone curve');point=null;before=null;debounceSave()};c.ondblclick=e=>{const[px,py]=pos(e),pts=current.edits.curve[curveChannel],i=pts.findIndex(p=>p[0]!==0&&p[0]!==255&&Math.hypot(p[0]-px,p[1]-py)<22);if(i>=0)commit('Remove curve point',()=>pts.splice(i,1))}}

function buildMaskPanel(){const subject=`<div class="mask-type"><button id="subjectMaskBtn" aria-pressed="false">◎ Subject focus mask</button>${range('mask.size','Size',5,90,1)}${range('mask.feather','Feather',0,100,1)}${range('mask.subjectExposure','Subject exposure',-2,2,.01)}${range('mask.subjectClarity','Subject clarity',-100,100,1)}${range('mask.backgroundExposure','Background exposure',-2,2,.01)}${range('mask.backgroundBlur','Background blur',0,100,1)}</div>`;const sky=`<div class="mask-type"><button id="skyMaskBtn" aria-pressed="false">◒ Sky gradient mask</button>${range('mask.skyExposure','Sky exposure',-2,2,.01)}${range('mask.skyTemperature','Sky temperature',-100,100,1)}</div>`;const cleanup=`<div class="mask-type"><button id="cleanupMaskBtn" aria-pressed="false">✦ Spot cleanup</button><p class="curve-help">Click dust or a blemish; Luma samples nearby texture.</p><button id="undoSpot" class="mini-btn">Remove last spot</button></div>`;$('#maskControls').innerHTML=`<label class="check-row">Enable current mask<input type="checkbox" data-check-path="mask.enabled"></label><label class="check-row">Invert mask<input type="checkbox" data-check-path="mask.invert"></label><label class="check-row">Show overlay<input type="checkbox" data-check-path="mask.show"></label>${subject}${sky}${cleanup}`;bindRanges($('#maskControls'));$$('#maskControls [data-check-path]').forEach(el=>el.onchange=()=>commit(el.dataset.checkPath,()=>setPath(current.edits,el.dataset.checkPath,el.checked)));$('#subjectMaskBtn').onclick=()=>commit('Subject mask',()=>{current.edits.mask.enabled=true;current.edits.mask.type='subject';setTool('focus')});$('#skyMaskBtn').onclick=()=>commit('Sky mask',()=>{current.edits.mask.enabled=true;current.edits.mask.type='sky';setTool('')});$('#cleanupMaskBtn').onclick=()=>setTool('cleanup');$('#undoSpot').onclick=()=>commit('Remove spot',()=>current.edits.cleanup.pop())}
function updateMaskUI(){if(!current)return;const m=current.edits.mask;[['#subjectMaskBtn',m.enabled&&m.type==='subject'],['#skyMaskBtn',m.enabled&&m.type==='sky']].forEach(([selector,active])=>{const button=$(selector);button?.classList.toggle('active',active);button?.setAttribute('aria-pressed',String(active))});const overlay=$('#maskOverlay');overlay.classList.toggle('hidden',!m.enabled||!m.show||m.type==='sky');overlay.style.left=`${m.x*100}%`;overlay.style.top=`${m.y*100}%`;overlay.style.width=`${m.size*2}%`;overlay.style.height=`${m.size*1.44}%`}

function buildPresets(){const groups=['All',...new Set(presets.map(p=>p.group))];$('#presetGroups').innerHTML=groups.map((g,i)=>`<button class="${i?'':'active'}" data-group="${g}" aria-pressed="${!i}">${g}</button>`).join('');$$('#presetGroups button').forEach(b=>b.onclick=()=>{$$('#presetGroups button').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});renderPresetGrid(b.dataset.group)});renderPresetGrid('All')}
function renderPresetGrid(group='All'){const q=$('#presetSearch').value.toLowerCase();const list=presets.filter(p=>(group==='All'||p.group===group)&&p.name.toLowerCase().includes(q));$('#presetGrid').innerHTML=list.map(p=>`<button class="preset" data-name="${safeText(p.name)}" style="background:${p.style}"><b>${safeText(p.name)}</b><span>${safeText(p.group)} · ${safeText(p.source)}</span></button>`).join('');$$('.preset').forEach(b=>b.onclick=()=>applyPreset(presets.find(p=>p.name===b.dataset.name),+$('#presetAmount').value))}
function blendPreset(base,patch,t){const out=E.clone(base);function walk(dst,src,b){for(const[k,v]of Object.entries(src)){if(Array.isArray(v)){if(k==='rgb'||['red','green','blue'].includes(k))dst[k]=v.map(([px,py])=>[px,Math.max(0,Math.min(255,Math.round(px+(py-px)*t)))]);else dst[k]=E.clone(v)}else if(v&&typeof v==='object'){if(!dst[k])dst[k]={};walk(dst[k],v,b?.[k]||{})}else if(typeof v==='number'){const bv=typeof b?.[k]==='number'?b[k]:0;dst[k]=bv+(v-bv)*t}else if(typeof v==='boolean')dst[k]=t>0?v:b?.[k]||false;else dst[k]=t>0?v:b?.[k]}}walk(out,patch,base);return out}
function applyPreset(p,amount=100){
  if(!current)return;
  if(batchPresetMode){const targets=photos.filter(photo=>photo.selected),changes=targets.map(photo=>({id:photo.id,before:E.clone(photo.edits),after:blendPreset(photo.edits,p.patch,amount/100)}));batchPresetMode=false;if(!changes.length)return toast('Select photographs before applying a batch preset');if(!pushBulkHistory(changes,`Preset ${p.name} · ${targets.length} photos`))return;for(const change of changes){const photo=photos.find(candidate=>candidate.id===change.id);if(photo)photo.edits=E.clone(change.after)}clearPresetTracking();refreshControls();scheduleRender();debounceSave();if(view==='library')updateLibrary();toast(`${p.name} applied to ${targets.length} selected photos · Undo reverses the batch`);return}
  if(activePreset!==p){activePreset=p;presetBase=E.clone(current.edits)}const before=E.clone(current.edits),next=blendPreset(presetBase,p.patch,amount/100);current.edits=next;pushHistory(before,next,`Preset: ${p.name}`);refreshControls();scheduleRender();debounceSave();toast(`${p.name} · ${amount}%`)
}

async function importPhotos(items){
  try{if(!items)items=await window.desktop.pickImages()}catch(error){reportFailure('Choose photos',error,'The photo picker could not be opened.');return}
  if(!items?.length)return;let firstNew=null,added=0,limited=0;const knownPaths=new Set(photos.map(photo=>photo.filePath.toLowerCase()));
  for(const f of items){if(photos.length>=MAX_CATALOG_PHOTOS){limited++;continue}const filePath=typeof f?.filePath==='string'?f.filePath:'';if(!filePath)continue;const pathKey=filePath.toLowerCase();if(knownPaths.has(pathKey))continue;knownPaths.add(pathKey);const p=E.migratePhoto({...f,filePath,id:uid(),importedAt:Date.now()+added});photos.push(p);firstNew??=p;added++}
  if(!added)return toast(limited?'The catalog photo limit has been reached':'Those photos are already in the catalog');catalogDirty=true;const saved=saveCatalog();updateLibrary();selectPhoto(firstNew);toast(saved?`${added} photo${added===1?'':'s'} imported${limited?` · ${limited} skipped at the catalog limit`:''}`:`${added} photo${added===1?'':'s'} available for this session, but the catalog is not saved · back up before closing`)
}
function clearPreview(){const c=$('#canvas');if(c){c.width=1;c.height=1;c.getContext('2d')?.clearRect(0,0,1,1)}const h=$('#hist');h?.getContext('2d')?.clearRect(0,0,h.width,h.height)}
function clearPrefetch(){for(const im of prefetchCache.values()){im.onload=im.onerror=null;try{im.src=''}catch{}}prefetchCache.clear()}
function prefetchAround(p){
  const index=photos.indexOf(p);if(index<0)return;const wanted=[];for(let distance=1;distance<=PREFETCH_RADIUS;distance++){if(photos[index+distance])wanted.push(photos[index+distance]);if(photos[index-distance])wanted.push(photos[index-distance])}const wantedIds=new Set(wanted.slice(0,MAX_PREFETCH_IMAGES).map(x=>x.id));
  for(const[id,im]of prefetchCache)if(!wantedIds.has(id)){im.onload=im.onerror=null;try{im.src=''}catch{}prefetchCache.delete(id)}
  for(const photo of wanted.slice(0,MAX_PREFETCH_IMAGES)){if(prefetchCache.has(photo.id))continue;const im=new Image();im.crossOrigin='anonymous';im.decoding='async';im._lumaUrl=photo.url||`local-image://load?path=${encodeURIComponent(photo.filePath)}`;im.onerror=()=>{if(prefetchCache.get(photo.id)===im)prefetchCache.delete(photo.id)};prefetchCache.set(photo.id,im);im.src=im._lumaUrl}
}
function selectPhoto(p,{openEditor=true}={}){
  if(!p)return;current=p;activePreset=null;presetBase=null;const token=++imageLoadToken;renderGeneration++;renderQueued=false;clearPreview();syncCurrentIndicators();
  const cached=prefetchCache.get(p.id),nextImage=cached||new Image();prefetchCache.delete(p.id);sourceImage=nextImage;nextImage.crossOrigin='anonymous';nextImage.decoding='async';let settled=false;
  const finishFailure=error=>{if(settled||token!==imageLoadToken||current!==p)return;settled=true;clearTimeout(timer);nextImage.onload=nextImage.onerror=null;try{nextImage.src=''}catch{}p._loadError=true;clearPreview();setView('library');updateLibrary();console.error('[Luma] Load photo',error);toast(`Could not open ${p.name}. The file may be missing or unsupported; choose another photo.`)};
  const timer=setTimeout(()=>finishFailure(new Error('Image load timed out')),IMAGE_LOAD_TIMEOUT);
  nextImage.onload=()=>{if(settled||token!==imageLoadToken||current!==p)return;if(!nextImage.naturalWidth||!nextImage.naturalHeight)return finishFailure(new Error('Decoded image has no pixels'));settled=true;clearTimeout(timer);delete p._loadError;prefetchAround(p);if(openEditor||view==='edit'){scheduleRender();showEditor()}else syncCurrentIndicators()};
  nextImage.onerror=()=>finishFailure(new Error('Image decode failed'));
  const url=p.url=`local-image://load?path=${encodeURIComponent(p.filePath)}`;nextImage._lumaUrl=url;if(!cached)nextImage.src=url;else if(nextImage.complete)queueMicrotask(()=>nextImage.naturalWidth?nextImage.onload?.():nextImage.onerror?.());refreshControls();renderFilmstrip();updateUndoButtons()
}
