function showEditor(){view='edit';document.body.classList.remove('library-mode');$('#empty').classList.add('hidden');$('#library').classList.add('hidden');$('#editor').classList.remove('hidden');$('#filmstrip').classList.remove('hidden');$('#adjustPanel').classList.remove('hidden');updateViewTabs();updateActionState()}
