    toast('Preparing background export…');await new Promise(r=>setTimeout(r,30));
    const size=Math.max(0,Math.round(num($('#exportSize').value,0))),quality=Math.max(.1,Math.min(1,num($('#exportQuality').value,92)/100)),watermark=$('#exportWatermark').value.trim().slice(0,80),exportEdits=E.clone(photo.edits);exportEdits.pointColor.visualize=false;
