function setCompare(value){compare=!!value;$('#compareBtn')?.setAttribute('aria-pressed',String(compare));scheduleRender()}
function releaseOriginalShortcut(e){if((e.code==='Backslash'||e.key==='\\')&&compare)setCompare(false)}

function confirmCatalogRestore(restored){const dialog=$('#restoreConfirmDialog');$('#restoreConfirmSummary').textContent=`Incoming catalog: ${restored.photos.length} photograph${restored.photos.length===1?'':'s'}${restored.skipped?` (${restored.skipped} invalid entr${restored.skipped===1?'y':'ies'} skipped)`:''}. Current catalog: ${photos.length} photograph${photos.length===1?'':'s'}.`;dialog.returnValue='';dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='restore'),{once:true}))}

function bindGlobal(){
  $('#importBtn').onclick=$('#emptyImport').onclick=()=>runAsync('Import photos',()=>importPhotos(),'Photos could not be imported.');$$('.tab').forEach(t=>t.onclick=()=>setView(t.dataset.view));$('#exportBtn').onclick=()=>{if(!current)return toast('Import a photo first');$('#exportTarget').textContent=`Active photograph: ${current.name}`;updateExportOptions();$('#exportDialog').showModal()};$('#exportFormat').onchange=updateExportOptions;$('#doExport').onclick=e=>{e.preventDefault();if(e.currentTarget.form.reportValidity())doExport()};$('#exportDialog').addEventListener('close',cancelExportRender);
  $('#helpBtn').onclick=openHelpCenter;$('#openGuideBtn').onclick=()=>runAsync('Open help guide',openHelpGuide,'The guide could not be opened.');$('#startTutorialBtn').onclick=()=>{helpReturnFocus=null;$('#helpDialog').close();requestAnimationFrame(startTutorial)};$('#tutorialBack').onclick=()=>{if(tutorialStep>0){tutorialStep--;renderTutorialStep()}};$('#tutorialNext').onclick=()=>{if(tutorialStep>=tutorialSteps.length-1)finishTutorial('complete');else{tutorialStep++;renderTutorialStep()}};$('#tutorialSkip').onclick=$('#tutorialClose').onclick=()=>finishTutorial('skipped');$('#tutorialDialog').addEventListener('cancel',event=>{event.preventDefault();finishTutorial('skipped')});$('#tutorialDialog').addEventListener('close',()=>{clearTutorialTarget();document.body.classList.remove('tutorial-active')});$('#helpDialog').addEventListener('close',()=>{const returnTo=helpReturnFocus;helpReturnFocus=null;requestAnimationFrame(()=>{if(returnTo?.isConnected&&!returnTo.closest('dialog:not([open])'))returnTo.focus()})});window.addEventListener('resize',()=>{if($('#tutorialDialog').open)placeTutorial()});
  $('#compareBtn').onpointerdown=()=>setCompare(true);['pointerup','pointerleave','pointercancel'].forEach(n=>$('#compareBtn').addEventListener(n,()=>setCompare(false)));$('#compareBtn').onkeydown=e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();setCompare(true)}};$('#compareBtn').onkeyup=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();setCompare(false)}};$('#compareBtn').onblur=()=>setCompare(false);
  $('#rotateLeft').onclick=()=>commit('Rotate left',()=>current.edits.geometry.rotation90-=90);$('#rotateRight').onclick=()=>commit('Rotate right',()=>current.edits.geometry.rotation90+=90);$('#flipBtn').onclick=()=>commit('Flip',()=>current.edits.geometry.flipX=!current.edits.geometry.flipX);$('#resetBtn').onclick=()=>commit('Reset all',()=>current.edits=E.defaultEdits());
  $$('.panel-tabs button').forEach((b,index,buttons)=>{b.onclick=()=>switchRightPanel(b.dataset.panel);b.onkeydown=e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;e.preventDefault();const next=buttons[(index+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];switchRightPanel(next.dataset.panel);next.focus()}});$('#presetSearch').oninput=()=>renderPresetGrid($('#presetGroups .active')?.dataset.group||'All');$('#presetAmount').oninput=e=>{$('#presetAmountOut').value=e.target.value;if(activePreset&&current){const before=current.edits;current.edits=blendPreset(presetBase,activePreset.patch,+e.target.value/100);refreshControls();scheduleRender();debounceSave()}};
  $('#pickColorBtn').onclick=()=>setTool('color');$('#focusModeBtn').onclick=()=>{if(!current)return;if(!current.edits.mask.enabled||current.edits.mask.type!=='subject')commit('Subject mask',()=>{current.edits.mask.enabled=true;current.edits.mask.type='subject'});setTool('focus');switchRightPanel('mask');refreshControls()};$('#cleanupModeBtn').onclick=()=>{setTool('cleanup');switchRightPanel('mask')};$('#canvas').onclick=canvasClick;
  $('#fitBtn').onclick=()=>{$('#zoomRange').value=100;$('#canvas').style.transform='';$('#canvasWrap').classList.remove('zoomed');$('#zoomLabel').value='Fit'};$('#zoomRange').oninput=e=>{const z=e.target.value/100;$('#canvas').style.transform=`scale(${z})`;$('#canvasWrap').classList.toggle('zoomed',z>1);$('#zoomLabel').value=e.target.value+'%'};
  $('#undoBtn').onclick=()=>{const[u,r]=historyStacks(),item=u.pop();if(!item)return;clearPresetTracking();r.push(item);applyHistoryItem(item,'before');refreshControls();scheduleRender();if(view==='library')updateLibrary();debounceSave();updateUndoButtons()};$('#redoBtn').onclick=()=>{const[u,r]=historyStacks(),item=r.pop();if(!item)return;clearPresetTracking();u.push(item);applyHistoryItem(item,'after');refreshControls();scheduleRender();if(view==='library')updateLibrary();debounceSave();updateUndoButtons()};
  $$('.side[data-filter]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.filter===activeFilter));b.onclick=()=>{activeFilter=b.dataset.filter;libraryRenderLimit=LIBRARY_PAGE_SIZE;$$('.side[data-filter]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});setView('library')}});const refreshLibraryFilter=()=>{libraryRenderLimit=LIBRARY_PAGE_SIZE;updateLibrary()};$('#search').oninput=$('#filterRating').onchange=$('#sort').onchange=refreshLibraryFilter;$('#loadMoreBtn').onclick=()=>{libraryRenderLimit+=LIBRARY_PAGE_SIZE;updateLibrary()};
  $('#selectAllBtn').onclick=()=>{filteredPhotos().forEach(p=>p.selected=true);updateLibrary()};$('#deselectBtn').onclick=()=>{photos.forEach(p=>p.selected=false);updateLibrary()};$('#compareSelectedBtn').onclick=()=>runAsync('Compare selected photos',compareSelected,'The selected photos could not be compared.');$('#compareDialog').addEventListener('close',()=>{$$('#compareDialog canvas').forEach(c=>{c.width=c.height=1})});$('#batchPresetBtn').onclick=()=>{const first=photos.find(p=>p.selected);if(!first)return;batchPresetMode=true;selectPhoto(first);switchRightPanel('presets');toast('Choose a preset to apply to the selection')};$('#batchBtn').onclick=syncSelected;$('#cullBtn').onclick=()=>runAsync('Analyze catalog',analyzeCatalog,'Catalog analysis stopped because a photo could not be processed.');
  $('#mergeBtn').onclick=()=>{$('#mergeDialog').showModal()};$('#hdrMerge').onclick=e=>{e.preventDefault();$('#mergeDialog').close();runAsync('HDR merge',()=>mergeSelected('hdr'),'HDR merge failed. Check that all selected files are available.')};$('#panoMerge').onclick=e=>{e.preventDefault();$('#mergeDialog').close();runAsync('Panorama merge',()=>mergeSelected('pano'),'Panorama merge failed. Try fewer or smaller photos.')};
  $('#backupBtn').onclick=()=>runAsync('Back up catalog',async()=>{flushCatalog();const path=await window.desktop.saveCatalog(JSON.stringify({app:'Luma Darkroom',version:2,createdAt:new Date().toISOString(),photos:catalogRecords()},null,2));if(path)toast('Catalog backup saved')},'Catalog backup could not be saved.');
  $('#restoreBtn').onclick=()=>runAsync('Restore catalog',async()=>{const text=await window.desktop.openCatalog();if(!text)return;const restored=parseCatalogText(text,'backup');if(!await confirmCatalogRestore(restored))return;const preRestore=JSON.stringify({app:'Luma Darkroom',version:2,createdAt:new Date().toISOString(),reason:'Pre-restore catalog backup',photos:catalogRecords()},null,2),backupPath=await window.desktop.saveCatalog(preRestore);if(!backupPath)return toast('Restore canceled · the current catalog was not backed up');installCatalog(restored.photos);catalogDirty=true;const saved=saveCatalog();updateLibrary();if(photos[0])selectPhoto(photos[0]);else setView('library');toast(saved?`${photos.length} catalog entries restored · previous catalog backed up${restored.skipped?` · ${restored.skipped} invalid skipped`:''}`:`${photos.length} entries restored for this session, but the catalog is not saved · previous catalog backup is safe`)},'That catalog file is invalid or too large.');
  $('#saveMetadata').onclick=e=>{e.preventDefault();if(!metadataPhoto)return;metadataPhoto.rating=metadataRating;metadataPhoto.flag=$('#flagEditor').value;metadataPhoto.label=$('#labelEditor').value;metadataPhoto.tags=[...new Set($('#tagsEditor').value.split(',').map(s=>s.trim()).filter(Boolean).slice(0,100))];metadataPhoto.caption=$('#captionEditor').value.slice(0,2000);debounceSave();updateLibrary();$('#metadataDialog').close()};
  window.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('drag')});window.addEventListener('dragleave',e=>{if(e.target===document.documentElement||e.target===document.body)document.body.classList.remove('drag')});window.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('drag');const supported=/\.(jpe?g|png|webp|bmp|gif|tiff?|avif|hei[cf]|dng|cr[23]|nef|nrw|arw|srf|sr2|raf|rw2|orf|pef|x3f)$/i,items=[];for(const f of [...e.dataTransfer.files].filter(f=>supported.test(f.name))){try{const filePath=window.desktop.pathForFile(f);if(filePath)items.push({filePath,name:f.name,url:`local-image://load?path=${encodeURIComponent(filePath)}`})}catch(error){console.warn('[Luma] Dropped file could not be resolved',error)}}items.length?runAsync('Import dropped photos',()=>importPhotos(items),'Dropped photos could not be imported.'):toast('No supported photographs were found in that drop')});
  window.addEventListener('keydown',handleShortcut);window.addEventListener('keyup',releaseOriginalShortcut);window.addEventListener('blur',()=>{if(compare)setCompare(false)});switchRightPanel('edit');updateExportOptions();updateActionState();
}

function parseCatalogText(raw,source='catalog'){
  if(typeof raw!=='string'||raw.length>MAX_CATALOG_BYTES)throw new RangeError('Catalog is empty or too large');const data=JSON.parse(raw),list=Array.isArray(data)?data:data?.photos;if(!Array.isArray(list)||list.length>MAX_CATALOG_PHOTOS)throw new Error('Catalog photo list is invalid');
  if(!Array.isArray(data)&&data.checksum&&checksum(JSON.stringify(list))!==data.checksum)throw new Error('Catalog checksum does not match');
  const migrated=[],ids=new Set(),paths=new Set();let skipped=0;
  for(const record of list){
    try{if(!record||typeof record!=='object'||typeof record.filePath!=='string'||!record.filePath.trim()||record.filePath.length>32767)throw new Error('Invalid photo record');const pathKey=record.filePath.toLowerCase();if(paths.has(pathKey)){skipped++;continue}paths.add(pathKey);const photo=E.migratePhoto(record);if(!photo.id||ids.has(photo.id))photo.id=uid();ids.add(photo.id);migrated.push(photo)}catch(error){skipped++;console.warn(`[Luma] Skipped invalid ${source} entry`,error)}
  }
  return{photos:migrated,skipped,savedAt:num(data?.savedAt,0),generation:num(data?.generation,0),source}
}
function installCatalog(nextPhotos){
  imageLoadToken++;renderGeneration++;current=null;sourceImage.onload=sourceImage.onerror=null;sourceImage=new Image();clearPreview();clearPrefetch();undoByPhoto.clear();redoByPhoto.clear();historyLru.clear();libraryRenderLimit=LIBRARY_PAGE_SIZE;photos=nextPhotos
}
function loadCatalog(){
  const specs=[[RECOVERY_KEY,'recovery',3],[CATALOG_KEY,'catalog',4],[BACKUP_KEY,'last good backup',2],[LEGACY_KEY,'legacy catalog',1]],candidates=[];let foundRaw=false,invalid=0;
  for(const[key,label,priority]of specs){const raw=storageGet(key);if(!raw)continue;foundRaw=true;try{candidates.push({...parseCatalogText(raw,label),priority})}catch(error){invalid++;console.warn(`[Luma] Could not read ${label}`,error)}}
  if(!candidates.length){installCatalog([]);if(foundRaw)toast('The saved catalog was damaged and could not be opened. Its data was preserved for backup.');return}
  candidates.sort((a,b)=>(b.generation||b.savedAt)-(a.generation||a.savedAt)||b.priority-a.priority);const chosen=candidates[0];catalogGeneration=Math.max(0,chosen.generation||chosen.savedAt);installCatalog(chosen.photos);
  if(chosen.source!=='catalog'){catalogDirty=true;setTimeout(()=>saveCatalog(),0);toast(`Recovered ${photos.length} photos from ${chosen.source}${chosen.skipped?` · ${chosen.skipped} invalid skipped`:''}`)}else if(chosen.skipped)toast(`Catalog opened · ${chosen.skipped} invalid entr${chosen.skipped===1?'y':'ies'} skipped`)
}
function installReliabilityGuards(){
  window.addEventListener('error',event=>{if(event.error)reportFailure('Unhandled renderer error',event.error)});
  window.addEventListener('unhandledrejection',event=>{event.preventDefault();reportFailure('Unhandled async error',event.reason)});
  window.addEventListener('pagehide',flushCatalog);window.addEventListener('beforeunload',event=>{if(catalogDirty&&!saveCatalog({silent:true})){event.preventDefault();event.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushCatalog()});setInterval(flushCatalog,5000)
}
installReliabilityGuards();buildAdjustments();buildMaskPanel();buildPresets();bindGlobal();refreshWatermarkHistory();loadCatalog();updateLibrary();if(photos.length)selectPhoto(photos[0]);scheduleFirstRunTutorial();
